@Test
    public void shouldReturnKeyByValue() {

        // Given

        Map<String, String> map = new HashMap<>();
        map.put("key1", "value1");
        map.put("key2", "value2");
        map.put("key3", "value3");

        // When
        String key = Util.getKeyByValue(map, "value1");

        // Then
        assertEquals("key1", key);
    }

